import type { Seed } from './roadmap-build';

// AI & LLMs learning path — 160 questions (20 levels × 8), ordered easiest →
// hardest, teaching how modern AI and large language models work: from "what is
// AI?" through tokens, transformers, prompting, RAG, agents and the model
// landscape. Built like the other single-list topics (Git/Node) via buildRoadmap
// in roadmap-questions.ts (ids rm-ai-1 … rm-ai-160, 8 per level).
export const aiSeeds: Seed[] = [
  // Level 1 — What is AI?
  { q: "What does the term 'artificial intelligence' (AI) most broadly refer to?", opts: ["A single computer program that thinks exactly like a human brain","Any computer connected to the internet","A type of physical robot with arms and legs","The field of building computer systems that perform tasks normally requiring human intelligence"], a: 3, e: "AI is the broad field of creating systems that perform tasks we associate with human intelligence, such as reasoning, perception, and language. It is not limited to robots or any single program.", tags: ["AI","basics"], intro: "Let's start with the big picture." },
  { q: "How are machine learning (ML) and artificial intelligence related?", opts: ["Machine learning is a subfield of artificial intelligence","ML and AI are completely unrelated fields","AI is a subfield of machine learning","They are exactly the same thing with two names"], a: 0, e: "Machine learning is one approach within the broader field of AI, where systems learn patterns from data rather than following only hand-written rules.", tags: ["AI","ML"] },
  { q: "Where does deep learning fit relative to AI and machine learning?", opts: ["Deep learning is broader than AI","Deep learning has nothing to do with machine learning","Deep learning is a subset of machine learning, which is a subset of AI","AI is a subset of deep learning"], a: 2, e: "The standard nesting is AI > machine learning > deep learning. Deep learning is ML that uses many-layered neural networks.", tags: ["AI","deep learning"] },
  { q: "What best describes 'narrow AI' (also called weak AI)?", opts: ["AI that is smarter than humans at every possible task","AI that has genuine consciousness and feelings","AI that can only run on a single narrow computer chip","AI designed and trained to perform a specific task or narrow set of tasks"], a: 3, e: "Narrow AI is built for particular tasks, like spam filtering or image tagging. Essentially all AI in use today is narrow AI.", tags: ["AI","narrow AI"] },
  { q: "What would 'artificial general intelligence' (AGI) mean?", opts: ["AI that controls general-purpose hardware","AI used only by the general public","AI that can match or exceed human ability across the full range of cognitive tasks","Any AI that can play more than one video game"], a: 2, e: "AGI refers to a hypothetical system with broad, human-level competence across diverse tasks. It does not yet exist; today's systems are narrow AI.", tags: ["AI","AGI"] },
  { q: "Which of these is a common everyday example of AI in action?", opts: ["A pocket calculator adding two numbers","A streaming service recommending shows based on your viewing history","A spreadsheet summing a column with a fixed formula","A light switch turning a bulb on and off"], a: 1, e: "Recommendation systems learn from data about your behavior to make predictions, a hallmark of AI. A calculator or fixed formula just executes predetermined rules.", tags: ["AI","examples"] },
  { q: "Before modern machine learning, many early AI systems worked mainly by:", opts: ["Following large sets of hand-written rules created by experts","Learning automatically from millions of examples","Randomly guessing until they got the right answer","Copying answers directly from the internet"], a: 0, e: "Classic 'symbolic' or rule-based AI relied on explicitly programmed if-then rules and expert knowledge, rather than learning patterns from data.", tags: ["AI","history"] },
  { q: "Which statement about today's AI systems is most accurate?", opts: ["They are conscious and self-aware like humans","They are narrow tools that can be very capable within their trained domains but lack general human-like understanding","They can already do absolutely any task a human can do","They never make mistakes once trained"], a: 1, e: "Current AI can be highly capable in specific areas yet remains narrow, can make errors, and does not possess general human-like understanding or consciousness.", tags: ["AI","limitations"] },
  // Level 2 — Machine Learning Basics
  { q: "What is the core idea behind machine learning?", opts: ["A programmer writes every rule the system will ever use by hand","The computer copies an existing program exactly","Humans manually label every possible answer in advance forever","A system learns patterns from data so it can make predictions or decisions on new data"], a: 3, e: "In machine learning, the system infers patterns from training data and generalizes them to make predictions on new, unseen inputs.", tags: ["ML","basics"] },
  { q: "In supervised learning, the training data consists of:", opts: ["Inputs only, with no correct answers provided","Rewards and punishments from an environment","Random noise with no structure","Inputs paired with the correct outputs (labels)"], a: 3, e: "Supervised learning uses labeled examples, input paired with the desired output, so the model learns to map inputs to correct outputs.", tags: ["ML","supervised"] },
  { q: "Which task is a typical example of unsupervised learning?", opts: ["Predicting tomorrow's temperature from labeled historical data","Classifying emails as spam using labeled examples","Grouping customers into clusters based on similar behavior without predefined labels","Training a robot using rewards for good moves"], a: 2, e: "Unsupervised learning finds structure in unlabeled data; clustering similar items together is a classic example.", tags: ["ML","unsupervised"] },
  { q: "Reinforcement learning is best described as learning by:", opts: ["Trial and error, guided by rewards and penalties from an environment","Memorizing a fixed table of answers","Reading labeled input-output pairs","Sorting data into clusters"], a: 0, e: "In reinforcement learning, an agent takes actions in an environment and learns from the rewards or penalties it receives to maximize long-term reward.", tags: ["ML","reinforcement"] },
  { q: "In machine learning, what is the difference between training and inference?", opts: ["Training is when the model learns from data; inference is when the trained model makes predictions on new inputs","Training uses the model to make predictions; inference builds the model","They are the same step","Training happens only on phones; inference only on servers"], a: 0, e: "Training is the learning phase where parameters are adjusted using data. Inference is using the finished model to make predictions.", tags: ["ML","training","inference"] },
  { q: "In the language of machine learning, what are 'features'?", opts: ["The correct answers the model is trying to predict","The errors the model makes during training","The input variables or measurable properties used to make a prediction","The hardware used to run the model"], a: 2, e: "Features are the input attributes (for example, a house's size and location) that the model uses to predict the target.", tags: ["ML","features"] },
  { q: "In supervised learning, the 'label' refers to:", opts: ["A sticker placed on the training computer","The correct output or answer associated with each training example","The name of the algorithm being used","An input feature that is ignored"], a: 1, e: "The label is the ground-truth output for an example, such as 'spam' or 'not spam', that the model learns to predict.", tags: ["ML","labels"] },
  { q: "In machine learning, what is a 'model'?", opts: ["A human expert who supervises training","A learned function, defined by parameters, that maps inputs to outputs","The raw dataset before any learning","A physical scale replica of a computer"], a: 1, e: "A model is the artifact produced by training: a parameterized function that takes inputs and produces predictions.", tags: ["ML","models"] },
  // Level 3 — Neural Networks
  { q: "An artificial neural network is loosely inspired by:", opts: ["The way muscles contract","The structure of computer hard drives","How electricity flows through a single wire","Networks of interconnected neurons in the brain"], a: 3, e: "Artificial neural networks take loose inspiration from biological neurons that pass signals to one another, though they are mathematical, not biological.", tags: ["neural networks","basics"] },
  { q: "In a neural network, what do the 'weights' represent?", opts: ["The physical mass of the hardware","Adjustable parameters that determine the strength of connections between neurons","The number of layers in the network","The labels in the training set"], a: 1, e: "Weights are the tunable parameters that scale the inputs to each neuron; learning means adjusting these weights to reduce error.", tags: ["neural networks","weights"] },
  { q: "A typical feedforward neural network is organized into:", opts: ["A single neuron only","Only an output layer","An input layer, one or more hidden layers, and an output layer","A circular ring with no start or end"], a: 2, e: "Feedforward networks pass data from an input layer through hidden layers to an output layer, with each layer transforming the previous one's output.", tags: ["neural networks","layers"] },
  { q: "What does the word 'deep' mean in 'deep learning'?", opts: ["The neural network has many hidden layers","The network is trained for a very long time","The data is stored deep underground","The model uses only one powerful neuron"], a: 0, e: "'Deep' refers to network depth, the presence of many hidden layers, which lets the model learn increasingly abstract representations.", tags: ["deep learning","layers"] },
  { q: "What is the main purpose of an activation function in a neuron?", opts: ["To store the training data","To introduce non-linearity so the network can learn complex patterns","To delete unused neurons","To label the input data"], a: 1, e: "Activation functions add non-linearity; without them, stacking layers would only produce a linear model unable to capture complex relationships.", tags: ["neural networks","activation"] },
  { q: "Which of the following is a commonly used activation function?", opts: ["SQL","JPEG","ReLU (rectified linear unit)","TCP"], a: 2, e: "ReLU is one of the most widely used activation functions. The other options are unrelated technologies (a query language, an image format, and a network protocol).", tags: ["neural networks","activation"] },
  { q: "During training, how does a neural network typically improve?", opts: ["By randomly rewriting its own source code","By adding more training data to its memory at inference time","By deleting its hidden layers one by one","By adjusting its weights to reduce the error between its predictions and the correct answers"], a: 3, e: "Training uses optimization (commonly gradient descent with backpropagation) to nudge weights in directions that reduce prediction error.", tags: ["neural networks","training"] },
  { q: "What is backpropagation used for in neural networks?", opts: ["Computing how each weight contributed to the error so the weights can be updated","Sending the network's output back to the user","Backing up the model to a hard drive","Reversing the order of the input data"], a: 0, e: "Backpropagation efficiently computes gradients of the loss with respect to each weight, enabling the optimizer to update weights and reduce error.", tags: ["neural networks","backpropagation"] },
  // Level 4 — What is an LLM?
  { q: "A service predicts and generates text from a model trained on a very large text corpus. Which common term describes that model?", opts: ["OCR","RAG","LLM","CNN"], a: 2, e: "LLM means Large Language Model. It learns statistical patterns in language and generates sequences of tokens.", tags: ["LLM","basics"] },
  { q: "At their core, most modern LLMs are trained to do what?", opts: ["Search the live internet in real time","Predict the next token (piece of text) given the preceding text","Store every webpage word-for-word in a database","Translate only between two fixed languages"], a: 1, e: "LLMs are fundamentally next-token predictors: given a sequence of text, they estimate the probability of what comes next and generate text token by token.", tags: ["LLM","next-token"] },
  { q: "Which of these is a well-known family of large language models?", opts: ["GPT (from OpenAI)","Photoshop","Excel","Linux"], a: 0, e: "GPT is OpenAI's family of large language models. Other prominent families include Anthropic's Claude and Google's Gemini.", tags: ["LLM","models"] },
  { q: "An assistant must answer questions and call a search API when its stored knowledge is insufficient. Which setup fits?", opts: ["A classifier with no generated output","A text embedding model by itself","A static autocomplete dictionary","A language model with controlled tool access"], a: 3, e: "A tool-enabled language model can decide when it needs external information and call an approved search function. The application still needs validation and permission boundaries.", tags: ["LLM","tools"] },
  { q: "An assistant must answer from private documents that change every day. Which approach best grounds its response?", opts: ["Retrieve relevant documents and include them as model context","Increase temperature so the model explores more answers","Fine-tune once and assume the documents never change","Ask the model to rely only on its original training data"], a: 0, e: "Retrieval-augmented generation can supply current, private source text at request time. The model can then answer from that context instead of guessing from training data.", tags: ["LLM","RAG"] },
  { q: "Which of the following is something LLMs are generally good at?", opts: ["Guaranteeing perfectly accurate facts about very recent events","Knowing today's date and your private files automatically","Generating and summarizing fluent text and answering many questions","Performing flawless large-number arithmetic with no errors"], a: 2, e: "LLMs excel at fluent language tasks like drafting, summarizing, and answering. They can struggle with up-to-the-minute facts and precise arithmetic.", tags: ["LLM","capabilities"] },
  { q: "A model gives a fluent answer and invents a research citation that does not exist. What is this failure called?", opts: ["A context-window overflow that prevents any output","A hallucination: plausible-sounding but false or fabricated output","A refusal, because the model declined the requested task","Prompt injection, because external text changed the model's instructions"], a: 1, e: "A hallucination is generated content that sounds plausible but is not grounded in fact or the supplied sources. Important claims still need verification.", tags: ["LLM","hallucination"] },
  { q: "Why might a standalone LLM be unable to tell you about an event from last week?", opts: ["Its responses are always delayed by exactly seven days","LLMs cannot process dates at all","It can only discuss fictional events","Its training data has a knowledge cutoff, so it lacks information after that date unless given tools or new context"], a: 3, e: "An LLM's parametric knowledge is frozen at its training cutoff. Without web access or supplied context, it cannot know about events after that point.", tags: ["LLM","knowledge cutoff"] },
  // Level 5 — Tokens & Tokenization
  { q: "An LLM API reports that a prompt used 37 input tokens even though it contains fewer than 37 words. What is a token?", opts: ["Exactly one complete sentence, regardless of its length","A unit of text, often a word or part of a word, that the model processes","An API credential counted once for each request","A Unicode character, with every character always counted separately"], a: 1, e: "Models process sequences of tokens. A tokenizer may split one word into several pieces or combine punctuation with nearby text, so token count does not equal word count.", tags: ["tokens","basics"] },
  { q: "Why do LLMs break text into tokens rather than processing raw characters or whole words only?", opts: ["Because tokens are encrypted for security","Because computers cannot read letters","Subword tokens balance vocabulary size and flexibility, handling rare and new words efficiently","Because each token must be exactly one byte"], a: 2, e: "Subword tokenization keeps the vocabulary manageable while still representing rare or novel words by combining smaller pieces.", tags: ["tokens","tokenization"] },
  { q: "Roughly how much English text does one token correspond to on average for many modern tokenizers?", opts: ["About 100 words","Exactly one full paragraph","Exactly one letter, always","About three-quarters of a word (a few characters)"], a: 3, e: "A common rule of thumb is that one token is about 4 characters or roughly 0.75 words of English, though it varies by tokenizer and language.", tags: ["tokens","counting"] },
  { q: "A long, uncommon word like 'antidisestablishmentarianism' is most likely to be:", opts: ["A single token","Ignored entirely by the model","Converted into an image","Split into several subword tokens"], a: 3, e: "Rare or long words are typically broken into multiple subword tokens, while common short words often map to a single token.", tags: ["tokens","subwords"] },
  { q: "Why should an application track both input and output token counts for LLM requests?", opts: ["Only output tokens count toward any model limit or bill","They commonly affect usage cost and how much content fits in the context window","They determine which UI theme the model returns","They measure spelling quality but not resource usage"], a: 1, e: "Providers commonly meter usage and define context limits in tokens. Long prompts and responses can therefore increase cost or exceed the model’s available context.", tags: ["tokens","cost","limits"] },
  { q: "Which factor most affects how a given piece of text is split into tokens?", opts: ["The specific tokenizer used by the model","The user's typing speed","The brightness of the screen","The time of day"], a: 0, e: "Different models use different tokenizers, so the same text can produce different token counts depending on the model.", tags: ["tokens","tokenization"] },
  { q: "When an LLM generates a response, it produces the output:", opts: ["All at once as a finished essay with no intermediate steps","Only as whole paragraphs chosen from a fixed list","One token at a time, each conditioned on the tokens so far","By editing a pre-written template word for word"], a: 2, e: "Generation is autoregressive: the model emits tokens sequentially, feeding each new token back in to help predict the next one.", tags: ["tokens","generation"] },
  { q: "Compared with English, text in some other languages or with many emojis and symbols often:", opts: ["Can require more tokens to represent the same amount of meaning","Always uses exactly the same number of tokens","Cannot be tokenized at all","Uses zero tokens"], a: 0, e: "Tokenizers are often optimized for English, so other scripts, emojis, and unusual symbols can consume more tokens per character or word.", tags: ["tokens","languages"] },
  // Level 6 — Training Data & Datasets
  { q: "What is 'pretraining' for an LLM?", opts: ["A warm-up the model does before each question","The initial phase where the model learns general language patterns from a large text corpus","Training the user how to write prompts","Testing the model on a final exam"], a: 1, e: "Pretraining is the large-scale phase where the model learns broad language and world patterns from massive text datasets, before any task-specific tuning.", tags: ["training data","pretraining"] },
  { q: "What is a 'corpus' in the context of training LLMs?", opts: ["A type of neural network layer","A single web page","The model's output buffer","A large collection of text used as training data"], a: 3, e: "A corpus is a large body of text gathered for training. Pretraining corpora can include web pages, books, code, and more.", tags: ["training data","corpus"] },
  { q: "Why does the quality of training data matter so much for an LLM?", opts: ["It does not; only the quantity matters","Quality only affects the model's file size","Models learn patterns from their data, so low-quality or erroneous data can degrade outputs","High-quality data makes the model run on less electricity"], a: 2, e: "Because models imitate patterns in their training data, noisy, low-quality, or incorrect data can lead to worse, less reliable outputs.", tags: ["training data","quality"] },
  { q: "Why is the scale (sheer size) of training data important for modern LLMs?", opts: ["Larger, more diverse data generally helps models learn broader and more robust patterns","Bigger data always guarantees a perfect model with no errors","Scale only matters for image models, not text","More data makes the model smaller"], a: 0, e: "Training on large, diverse corpora helps LLMs capture a wide range of language and knowledge, though scale alone does not eliminate errors or bias.", tags: ["training data","scale"] },
  { q: "A model's 'knowledge cutoff' refers to:", opts: ["The point in time after which the model's training data does not include new information","A maximum number of questions it can answer","The moment the model is shut down","A limit on how long an answer can be"], a: 0, e: "The knowledge cutoff is the date beyond which the model has no training data, so it is unaware of later events unless given new context or tools.", tags: ["training data","knowledge cutoff"] },
  { q: "How can bias enter an LLM?", opts: ["Only if a programmer deliberately codes it in by hand","Bias is impossible in AI systems","Only through the user's questions","Through biases present in the training data, which the model can learn and reproduce"], a: 3, e: "Models learn statistical patterns from their data, so societal or sampling biases in that data can be absorbed and reflected in the model's outputs.", tags: ["training data","bias"] },
  { q: "Why do AI developers often 'clean' or filter training data before pretraining?", opts: ["To make the files load faster only","To remove duplicates, spam, and harmful or low-quality content that could hurt the model","To translate everything into binary","To delete all punctuation"], a: 1, e: "Data cleaning and filtering remove noise, duplication, and harmful or low-value content, which generally improves the quality and safety of the trained model.", tags: ["training data","data cleaning"] },
  { q: "Why is the representativeness (diversity) of a training dataset important?", opts: ["It is irrelevant as long as the data is large","Diversity only changes the model's color output","If some topics, languages, or groups are underrepresented, the model may perform worse on them","Representative data removes the need for any testing"], a: 2, e: "Gaps or imbalances in the data can lead to uneven performance, with the model doing worse on underrepresented topics, languages, or groups.", tags: ["training data","representativeness","bias"] },
  // Level 7 — Transformers & Attention
  { q: "Most modern LLMs are built on which neural network architecture?", opts: ["The decision tree","The spreadsheet","The relational database","The transformer"], a: 3, e: "The transformer architecture, introduced in 2017, underpins essentially all modern large language models.", tags: ["transformers","architecture"] },
  { q: "Why can self-attention be expensive for a very long input sequence?", opts: ["It must store the entire training dataset in each request","It can compare every token with every other token","It runs one separate model for every output token","It converts every token into a full source document"], a: 1, e: "Standard self-attention forms relationships between pairs of token positions, so its time and memory cost grows roughly with the square of sequence length.", tags: ["transformers","attention"] },
  { q: "What does the self-attention mechanism let a model do?", opts: ["Weigh the relevance of different tokens in the input to each other when forming representations","Pay attention to its own hardware temperature","Ignore all but the first word","Attend only to the most recent token"], a: 0, e: "Self-attention lets each token consider and weigh all other tokens in the sequence, capturing relationships and context regardless of distance.", tags: ["transformers","attention"] },
  { q: "A key practical advantage of transformers over older RNNs (recurrent neural networks) is:", opts: ["They require no training data","They never make mistakes","They use no memory","They process tokens in parallel rather than strictly one after another, enabling efficient training at scale"], a: 3, e: "Unlike RNNs, which process sequences step by step, transformers can process all tokens in parallel, making them far more efficient to train on modern hardware.", tags: ["transformers","parallelism","RNN"] },
  { q: "Why did RNNs struggle with very long sequences compared to transformers?", opts: ["Information had to pass step by step, making it hard to retain long-range dependencies","RNNs could not run on computers","RNNs ignored the first half of every input","RNNs required exactly four words of input"], a: 0, e: "RNNs propagate information sequentially, which makes long-range dependencies hard to preserve. Attention lets transformers connect distant tokens directly.", tags: ["transformers","RNN"] },
  { q: "Because transformers do not process tokens in order inherently, they add 'positional encodings' in order to:", opts: ["Encrypt the input","Reduce the number of tokens","Give the model information about the order or position of tokens","Translate the text"], a: 2, e: "Self-attention is order-agnostic by itself, so positional encodings inject information about each token's position so word order is preserved.", tags: ["transformers","positional encoding"] },
  { q: "What is 'multi-head attention' in a transformer?", opts: ["Using multiple separate computers","Attending to multiple users simultaneously","Running several attention mechanisms in parallel so the model can focus on different relationships at once","Stacking many output layers"], a: 2, e: "Multi-head attention runs several attention 'heads' in parallel, each able to learn different types of relationships among tokens, then combines them.", tags: ["transformers","attention"] },
  { q: "A GPT-style model uses attention blocks rather than recurrence as its main sequence architecture. Which architecture is that?", opts: ["Translator","Transformer","Trainer","Tokenizer"], a: 1, e: "GPT means Generative Pre-trained Transformer. Transformer names the attention-based architecture used by the model.", tags: ["transformers","GPT"] },
  // Level 8 — Prompting Basics
  { q: "In the context of LLMs, what is a 'prompt'?", opts: ["The model's internal weights","The input text or instructions you give the model to guide its response","An error message","The model's training dataset"], a: 1, e: "A prompt is the input, your question, instructions, or context, that you provide to the model to elicit a response.", tags: ["prompting","basics"] },
  { q: "What is 'zero-shot' prompting?", opts: ["Giving the model exactly zero instructions","Running the model with no training","Turning off the model","Asking the model to do a task without providing any examples in the prompt"], a: 3, e: "Zero-shot prompting asks the model to perform a task directly, relying on its pretrained knowledge, without including worked examples.", tags: ["prompting","zero-shot"] },
  { q: "What is 'few-shot' prompting?", opts: ["Prompting only a few times per day","Using a model with few parameters","Including a small number of examples in the prompt to show the model the desired pattern","Limiting the answer to a few words"], a: 2, e: "Few-shot prompting provides a handful of input-output examples in the prompt so the model can infer the pattern and apply it to the new input.", tags: ["prompting","few-shot"] },
  { q: "Which prompt is most likely to produce a useful, focused answer?", opts: ["'Tell me about it.'","'Stuff.'","'Summarize this article in three bullet points for a beginner audience.'","'?'"], a: 2, e: "Clear, specific instructions, including the task, format, and audience, give the model the guidance it needs to produce a useful response.", tags: ["prompting","clarity"] },
  { q: "Why does giving an LLM clear, specific instructions usually help?", opts: ["It reduces ambiguity, so the model is more likely to produce the output you actually want","It makes the model run on less power","It increases the number of tokens for no reason","It is required or the model will crash"], a: 0, e: "Specific instructions reduce ambiguity about the task, format, and goal, helping the model align its output with your intent.", tags: ["prompting","clarity"] },
  { q: "In chat-style LLM interfaces, what is the purpose of a 'system' role or system prompt?", opts: ["To set overall instructions, persona, or rules that guide the assistant's behavior","To store the user's password","To display advertisements","To translate the conversation"], a: 0, e: "The system message provides high-level guidance, such as the assistant's role, tone, or constraints, that shapes how it responds throughout the conversation.", tags: ["prompting","roles"] },
  { q: "Including a few worked examples in a prompt is especially helpful when:", opts: ["You want the model to use less electricity","You want to hide information from the model","You never want consistent output","You want the output to follow a specific format or style the model might not guess"], a: 3, e: "Examples demonstrate the exact format or style you want, which is useful when a plain instruction might leave the desired structure ambiguous.", tags: ["prompting","few-shot","examples"] },
  { q: "Which of the following is generally good prompting practice?", opts: ["Being vague so the model has freedom","Specifying the desired format, audience, and constraints clearly","Using as few relevant details as possible","Never giving any context"], a: 1, e: "Clearly stating the format, audience, and any constraints helps the model produce output that matches your needs.", tags: ["prompting","best practices"] },
  // Level 9 — Context Windows
  { q: "What is an LLM's 'context window'?", opts: ["A pop-up window in the app","The model's training duration","The maximum amount of text (in tokens) the model can consider at once, including input and output","The size of the user's monitor"], a: 2, e: "The context window is the maximum span of tokens the model can attend to in a single request, covering both the prompt and the generated response.", tags: ["context window","basics"] },
  { q: "The context window is typically measured in:", opts: ["Tokens","Megabytes","Pixels","Seconds"], a: 0, e: "Context window size is expressed in tokens, the same units the model uses to read and generate text.", tags: ["context window","tokens"] },
  { q: "What usually happens if a conversation or document exceeds the model's context window?", opts: ["The model automatically gains more memory","The model translates it","Nothing; context windows are unlimited","Older or excess content must be truncated or dropped, so the model can lose access to it"], a: 3, e: "When input exceeds the window, content must be trimmed or summarized; anything dropped is no longer directly visible to the model.", tags: ["context window","truncation"] },
  { q: "Within a single request, the context window must accommodate:", opts: ["Only the input prompt","Both the input tokens and the output tokens together","Only the model's output","Neither input nor output"], a: 1, e: "The context window is shared by the prompt and the generated response, so a very long prompt leaves less room for output, and vice versa.", tags: ["context window","tokens"] },
  { q: "Why is a larger context window useful?", opts: ["It makes the model immune to mistakes","It removes the need for any prompt","It lets the model consider more information at once, such as long documents or longer conversations","It always makes responses shorter"], a: 2, e: "A bigger context window allows the model to take in more text, like lengthy documents or extended chats, without losing earlier content.", tags: ["context window","long context"] },
  { q: "Which statement about modern LLM context windows (as of 2024-2026) is most accurate?", opts: ["Many leading models now support very large windows, on the order of hundreds of thousands of tokens or more","They are all fixed at exactly 100 tokens","No model can exceed 1,000 tokens","Context windows have shrunk over time"], a: 0, e: "Context windows have grown dramatically; several frontier models now handle hundreds of thousands of tokens, and some advertise around a million.", tags: ["context window","current"] },
  { q: "A practical reason to manage context length (rather than always sending everything) is:", opts: ["Longer context always improves accuracy with no downside","More tokens can increase cost and latency, and very long inputs may dilute the model's focus","Models charge per word regardless of tokens","Context length has no effect on cost"], a: 1, e: "Sending more tokens raises cost and can slow responses, and stuffing the window with irrelevant text can make it harder for the model to focus on what matters.", tags: ["context window","cost","best practices"] },
  { q: "Because an LLM is generally stateless between separate API calls, how does it 'remember' earlier parts of a conversation?", opts: ["It permanently stores every chat in its weights","It cannot use any earlier information ever","It downloads the history from the internet","The prior conversation is re-sent as part of the context in each request"], a: 3, e: "By default, the model does not retain memory between calls; conversation history is included in the context window of each new request so it stays available.", tags: ["context window","memory"] },
  // Level 10 — Embeddings & Vectors
  { q: "What is a text 'embedding'?", opts: ["A picture embedded in a document","A numerical vector that represents the meaning of text in a way computers can compare","A font style for displaying text","A compressed zip file of text"], a: 1, e: "An embedding is a vector of numbers that captures semantic meaning, so that similar texts have similar vectors.", tags: ["embeddings","basics"] },
  { q: "A key property of good text embeddings is that:", opts: ["Texts with similar meaning have vectors that are close together","Every text maps to the exact same vector","Vectors are always two-dimensional","Embeddings can only represent single letters"], a: 0, e: "Quality embeddings place semantically similar texts near each other in vector space, enabling meaning-based comparison.", tags: ["embeddings","similarity"] },
  { q: "Which measure is commonly used to compare how similar two embedding vectors are?", opts: ["Spell check","Cosine similarity","Word count","File size"], a: 1, e: "Cosine similarity measures the angle between two vectors and is a standard way to gauge semantic similarity between embeddings.", tags: ["embeddings","similarity"] },
  { q: "What is 'semantic search'?", opts: ["Searching only for exact keyword matches","Searching alphabetically","Searching based on meaning, using embeddings to find conceptually similar results even if the words differ","Searching by file date only"], a: 2, e: "Semantic search uses embeddings to match on meaning rather than exact keywords, so 'car' can match 'automobile' if they are semantically close.", tags: ["embeddings","semantic search"] },
  { q: "What is a vector database primarily designed to do?", opts: ["Store only plain text with no structure","Render 3D graphics","Replace all spreadsheets","Store and efficiently search high-dimensional embedding vectors by similarity"], a: 3, e: "Vector databases are optimized to store embeddings and quickly retrieve the most similar vectors to a query, powering semantic search and retrieval.", tags: ["embeddings","vector database"] },
  { q: "In retrieval-augmented generation (RAG), embeddings are typically used to:", opts: ["Find relevant documents to retrieve and add to the prompt so the LLM can use them","Train the model from scratch each time","Replace the language model entirely","Encrypt the user's data"], a: 0, e: "RAG embeds a query, retrieves the most similar stored documents, and inserts them into the prompt so the LLM can ground its answer in that content.", tags: ["embeddings","RAG"] },
  { q: "Each number (dimension) in an embedding vector roughly corresponds to:", opts: ["A specific letter of the alphabet","The position of the text on the page","A learned feature of meaning, not usually human-interpretable on its own","The color of the text"], a: 2, e: "Embedding dimensions encode learned latent features of meaning; individual dimensions are generally not directly interpretable by humans.", tags: ["embeddings","vectors"] },
  { q: "Why are embeddings useful for tasks like clustering or recommendations?", opts: ["They make text unreadable","They delete duplicate words","They only work on images","They turn text into numbers whose distances reflect semantic relationships, which algorithms can operate on"], a: 3, e: "By converting text into meaningful numeric vectors, embeddings let standard algorithms measure similarity, group related items, and power recommendations.", tags: ["embeddings","applications"] },
  // Level 11 — Sampling & Temperature
  { q: "What does raising the temperature parameter during text generation generally do?", opts: ["Makes the model's output more random and varied","Makes the model run faster on the GPU","Reduces the number of tokens the model can output","Forces the model to always pick the single most likely token"], a: 0, e: "Temperature scales the logits before sampling; higher values flatten the probability distribution, making less-likely tokens more probable and output more diverse.", tags: ["AI","sampling","temperature"], intro: "Start with the core knob." },
  { q: "Setting temperature to 0 (or very close to it) typically produces what behavior?", opts: ["Completely random gibberish","An error, since temperature cannot be zero","Greedy, near-deterministic output that picks the highest-probability token","Maximum creativity and variety"], a: 2, e: "A temperature near 0 sharpens the distribution so the model almost always selects the single most probable token, approximating greedy decoding and giving repeatable results.", tags: ["AI","temperature","determinism"] },
  { q: "How does top-p (nucleus) sampling decide which tokens to consider?", opts: ["It keeps the smallest set of top tokens whose cumulative probability exceeds p","It always keeps exactly p tokens regardless of their probability","It removes the p most likely tokens","It multiplies every probability by p"], a: 0, e: "Top-p sampling selects the smallest group of highest-probability tokens whose probabilities sum to at least p, then samples from that dynamic set.", tags: ["AI","sampling","top-p"] },
  { q: "What is the main difference between top-k and top-p sampling?", opts: ["Top-k is deterministic while top-p is always random","Top-k only works with temperature 0","There is no difference; they are two names for the same method","Top-k keeps a fixed number of tokens, while top-p keeps a variable number based on cumulative probability"], a: 3, e: "Top-k restricts sampling to the k most likely tokens (a fixed count), whereas top-p adapts the candidate set size to cover a probability mass p.", tags: ["AI","top-k","top-p"] },
  { q: "A developer wants the same prompt to return identical answers on every call for a regression test. Which setting is most appropriate?", opts: ["High temperature with a large top-k","Temperature near 0 (greedy decoding)","Top-p of 0.99","Maximum temperature"], a: 1, e: "Greedy decoding (temperature ~0) selects the most probable token each step, giving the most reproducible output, which is ideal for deterministic tests.", tags: ["AI","determinism","temperature"] },
  { q: "Why might a model still produce slightly different outputs even at temperature 0?", opts: ["Temperature 0 secretly adds noise","The model ignores temperature entirely","Floating-point non-determinism, batching, or hardware differences can change tie-breaking","It is impossible; temperature 0 is always bit-for-bit identical"], a: 2, e: "Greedy decoding is deterministic in theory, but floating-point rounding, GPU parallelism, and batching can alter results, so identical output is not strictly guaranteed.", tags: ["AI","determinism","sampling"] },
  { q: "For a brainstorming task where you want diverse, creative ideas, which configuration is most suitable?", opts: ["Temperature 0 and top-k of 1","Greedy decoding only","Top-k of 1 with any temperature","A higher temperature (e.g., around 0.8-1.0) with top-p sampling"], a: 3, e: "Higher temperature combined with nucleus sampling broadens the range of plausible tokens, encouraging more varied and creative completions.", tags: ["AI","sampling","temperature"] },
  { q: "What does the logit-to-probability step (the softmax) do in sampling, and how does temperature interact with it?", opts: ["Softmax converts raw logits into a probability distribution; temperature divides the logits before softmax to control sharpness","Softmax picks the maximum logit; temperature has no effect on it","Softmax adds temperature to each logit","Softmax removes low logits and temperature counts the tokens"], a: 0, e: "Logits are divided by the temperature and then passed through softmax; lower temperature sharpens the distribution toward the top token, higher temperature flattens it.", tags: ["AI","softmax","temperature"] },
  // Level 12 — Hallucinations & Limitations
  { q: "In the context of LLMs, what is a 'hallucination'?", opts: ["When the model refuses to answer","When the model produces fluent, confident text that is factually incorrect or fabricated","When the model runs out of tokens mid-sentence","When the model repeats the same word forever"], a: 1, e: "A hallucination is output that sounds plausible and confident but is not grounded in fact or the provided sources.", tags: ["AI","hallucination","limitations"] },
  { q: "Which statement best explains a root cause of hallucinations in LLMs?", opts: ["They are trained to predict likely next tokens, not to verify truth, so plausible-sounding errors can emerge","They intentionally lie to users","They only hallucinate when the temperature is exactly 0","They have a separate fact database that is usually offline"], a: 0, e: "LLMs optimize for statistically likely continuations, so when the right answer is uncertain they may generate fluent but unsupported content.", tags: ["AI","hallucination","training"] },
  { q: "A model states a wrong fact in a very confident tone. What does this illustrate about LLMs?", opts: ["Confident phrasing reliably signals correctness","The model must have been hacked","An LLM's tone or fluency is not a reliable indicator of factual accuracy","High confidence means the answer came from a verified source"], a: 2, e: "LLMs can express high confidence regardless of correctness; the style of the answer says nothing about whether it is true.", tags: ["AI","confidence","hallucination"] },
  { q: "What is a 'knowledge cutoff' for a language model?", opts: ["A limit on how many tokens it can read","A daily quota of questions","The maximum temperature allowed","The point in time after which the model has no built-in knowledge of events from its training data"], a: 3, e: "The knowledge cutoff is the date up to which the model's training data extends; it has no inherent knowledge of later events unless given that information.", tags: ["AI","knowledge-cutoff","limitations"] },
  { q: "Why do base LLMs sometimes struggle with multi-step arithmetic or precise calculation?", opts: ["They are forbidden from doing math","They generate answers token by token from patterns rather than executing exact computation","Math is disabled to save compute","They can only add, never multiply"], a: 1, e: "Without tools, LLMs approximate calculations from learned patterns rather than performing exact symbolic computation, so errors accumulate in multi-step math.", tags: ["AI","reasoning","limitations"] },
  { q: "Which approach most directly reduces factual hallucinations when asking about specific, current documents?", opts: ["Increasing the temperature","Asking the same question repeatedly","Providing the relevant source text in the prompt so the model can ground its answer","Using a longer system prompt of encouragement"], a: 2, e: "Grounding the model with the actual reference material lets it base answers on supplied facts rather than guessing, reducing fabrication.", tags: ["AI","hallucination","grounding"] },
  { q: "What is a reasonable way to detect a likely hallucination in an LLM's answer about a niche topic?", opts: ["Trust it because it is detailed","Check whether the answer is long","Assume anything stated twice is true","Verify specific claims (names, dates, citations) against an independent reliable source"], a: 3, e: "Independent verification of concrete, checkable details is the most reliable way to catch fabricated facts and bogus citations.", tags: ["AI","hallucination","verification"] },
  { q: "A user reports the model invented a plausible-looking academic citation that does not exist. This is best described as:", opts: ["A rate-limit error","A hallucinated (fabricated) reference, a known LLM failure mode","A tokenization bug","Correct behavior if the topic is obscure"], a: 1, e: "Fabricated citations are a classic hallucination pattern: the model produces a realistically formatted reference that has no real source behind it.", tags: ["AI","hallucination","citations"] },
  // Level 13 — Fine-tuning & RAG
  { q: "What does RAG (retrieval-augmented generation) do at a high level?", opts: ["Permanently retrains the model on new data with each query","Retrieves relevant external documents and adds them to the prompt so the model can use them when answering","Increases the model's temperature automatically","Compresses the model to run on a phone"], a: 1, e: "RAG fetches relevant context (often via vector search) and injects it into the prompt, grounding the model's answer in external, up-to-date information without changing the weights.", tags: ["AI","RAG","retrieval"] },
  { q: "What does fine-tuning a model actually change?", opts: ["The wording of the user's prompt","Only the temperature setting","The model's weights, by training further on a curated dataset","The retrieval index used at query time"], a: 2, e: "Fine-tuning updates the model's parameters using additional training examples, adapting its behavior or style beyond what prompting alone can do.", tags: ["AI","fine-tuning","training"] },
  { q: "A company needs the assistant to always answer using their constantly-changing internal knowledge base. Which approach fits best?", opts: ["Fine-tune the model nightly on everything","Use RAG to retrieve the latest relevant documents at query time","Raise the temperature so it guesses better","Rely on the model's pretraining knowledge"], a: 1, e: "RAG handles frequently changing information well because you update the document store, not the model, and retrieve fresh content per query.", tags: ["AI","RAG","grounding"] },
  { q: "When is fine-tuning typically a better choice than prompting or RAG?", opts: ["When you need to inject the latest news into every answer","When the underlying facts change every hour","When you want to avoid any training cost","When you need to consistently teach a specific style, format, or behavior that prompting cannot reliably enforce"], a: 3, e: "Fine-tuning excels at instilling a consistent tone, format, or specialized behavior, whereas dynamic factual freshness is better served by RAG.", tags: ["AI","fine-tuning","prompting"] },
  { q: "In a typical RAG pipeline, what is the usual role of embeddings?", opts: ["They set the model's temperature","They convert text into vectors so semantically similar passages can be found via similarity search","They translate the answer into another language","They compress the model weights"], a: 1, e: "Embeddings map text to vectors; the query embedding is compared against document embeddings to retrieve the most semantically relevant chunks.", tags: ["AI","RAG","embeddings"] },
  { q: "What is meant by 'grounding' an LLM's response?", opts: ["Lowering the temperature to zero","Limiting the response length","Tying the answer to specific, verifiable source material provided to the model","Running the model offline"], a: 2, e: "Grounding means basing the model's output on explicit supporting evidence (e.g., retrieved documents), which improves factual reliability and enables citations.", tags: ["AI","grounding","RAG"] },
  { q: "Which is a key limitation of fine-tuning compared to RAG for keeping answers up to date?", opts: ["Fine-tuning automatically learns tomorrow's facts","Fine-tuned knowledge is frozen at training time and requires retraining to update","Fine-tuning cannot change model behavior at all","Fine-tuning removes the need for any data"], a: 1, e: "Once fine-tuned, the model's knowledge is fixed until you retrain; RAG instead refreshes information by updating the retrievable corpus.", tags: ["AI","fine-tuning","RAG"] },
  { q: "A team wants both a consistent brand voice AND answers grounded in live product docs. What is a sensible strategy?", opts: ["Only fine-tune and never retrieve","Only retrieve and never adjust behavior","Combine approaches: fine-tune (or carefully prompt) for voice and use RAG for current facts","Increase top-p and hope for the best"], a: 2, e: "Fine-tuning or strong prompting can enforce voice while RAG supplies fresh, grounded facts; the two techniques are complementary, not mutually exclusive.", tags: ["AI","RAG","fine-tuning"] },
  // Level 14 — Using AI APIs
  { q: "Most modern chat LLM APIs accept input as a list of messages. What do the message 'roles' typically represent?", opts: ["The model's temperature levels","Different speakers/contexts such as system, user, and assistant","Pricing tiers","Token compression methods"], a: 1, e: "Chat APIs structure conversation with roles like system (instructions), user (the human), and assistant (the model's replies) so context is clear.", tags: ["AI","API","messages"] },
  { q: "On a typical pay-per-use LLM API, what is usually billed?", opts: ["Only the number of API calls, regardless of length","Only output characters","Tokens consumed, usually counting both input (prompt) and output (completion) tokens","A flat monthly fee with no per-use cost"], a: 2, e: "Most providers charge by tokens, with separate rates for input and output; longer prompts and longer responses both increase cost.", tags: ["AI","API","pricing"] },
  { q: "What is the purpose of 'streaming' a model's response from an API?", opts: ["It encrypts the response","It returns tokens incrementally as they are generated instead of waiting for the full completion","It reduces the total token cost to zero","It guarantees deterministic output"], a: 1, e: "Streaming sends partial output token-by-token, improving perceived latency by letting the user see text as it is produced.", tags: ["AI","API","streaming"] },
  { q: "An app gets HTTP 429 responses under heavy load. What does this most likely indicate?", opts: ["The model hallucinated","The API key is correct","Streaming finished successfully","A rate limit was exceeded and requests are being throttled"], a: 3, e: "HTTP 429 ('Too Many Requests') signals you've hit a rate or quota limit; typical fixes include backoff, retries, and request batching.", tags: ["AI","API","rate-limits"] },
  { q: "What is the typical difference between a system message and a user message in a chat API?", opts: ["They are identical and interchangeable","The system message sets overall behavior and instructions; the user message is the specific request from the human","The user message sets global rules; the system message is the human's turn","Only system messages cost tokens"], a: 1, e: "The system message establishes the assistant's role, constraints, and behavior, while the user message carries the actual query or task.", tags: ["AI","API","system-prompt"] },
  { q: "A robust strategy for handling transient rate-limit (429) errors when calling an LLM API is to:", opts: ["Immediately retry in a tight loop with no delay","Use exponential backoff with retries (and respect any Retry-After header)","Switch to temperature 0","Send all requests at once to finish faster"], a: 1, e: "Exponential backoff spaces out retries to let limits reset and reduces load, and honoring Retry-After follows the server's guidance.", tags: ["AI","API","rate-limits"] },
  { q: "Why is counting tokens (not just characters or words) important when working with model APIs?", opts: ["Tokens determine the model's temperature","Tokens are only relevant for images","Context windows and pricing are measured in tokens, so token count governs limits and cost","Token counts never affect cost"], a: 2, e: "Both the maximum context length and billing are defined in tokens, so accurate token estimates are needed to stay within limits and predict cost.", tags: ["AI","API","tokens"] },
  { q: "If a request would exceed the model's context window, what is a sound mitigation?", opts: ["Raise the temperature","Send the request twice","Remove the system message and hope it fits","Trim, summarize, or chunk the input so the prompt plus expected output fits within the token limit"], a: 3, e: "Because the context window caps total tokens, reducing input via truncation, summarization, or chunking is the standard way to fit within limits.", tags: ["AI","API","context-window"] },
  // Level 15 — Chat Assistants & System Prompts
  { q: "What is the primary role of a system prompt in a chat assistant?", opts: ["To display the final answer to the user","To set the assistant's persona, rules, and overall behavior for the conversation","To store the user's password","To set the GPU clock speed"], a: 1, e: "The system prompt configures how the assistant should behave (tone, constraints, role) across the conversation, before user turns begin.", tags: ["AI","system-prompt","assistants"] },
  { q: "How does a stateless chat API typically 'remember' earlier turns in a conversation?", opts: ["It stores the whole history on the model's server forever by default","It guesses based on the user's name","The client re-sends the prior messages (conversation history) with each new request","It cannot reference earlier turns at all"], a: 2, e: "Most chat completion APIs are stateless per call, so the application must include the relevant prior messages each time to maintain context.", tags: ["AI","conversation-state","API"] },
  { q: "As a conversation grows very long, what common problem arises and how is it often handled?", opts: ["The model gets faster; nothing needs handling","The history can exceed the context window, so older turns are summarized or trimmed","The temperature automatically rises","The system prompt is deleted to make room, with no downside"], a: 1, e: "Long histories can outgrow the context limit, so applications commonly summarize or drop older messages while preserving key context.", tags: ["AI","conversation-state","context-window"] },
  { q: "In a well-designed assistant, if a user message conflicts with the system prompt's safety rules, what should generally happen?", opts: ["The user instruction always overrides safety rules","The assistant should crash","The assistant should follow its guardrails and decline the unsafe request","The assistant should switch to a random topic"], a: 2, e: "Guardrails set at the system level are meant to take precedence over user attempts to bypass them, so the assistant should refuse unsafe requests.", tags: ["AI","guardrails","system-prompt"] },
  { q: "What are 'guardrails' in the context of an AI assistant?", opts: ["Hardware cooling fins","Constraints and safety controls that keep the assistant's behavior within intended bounds","A type of embedding","The model's token limit"], a: 1, e: "Guardrails are policies, filters, and instructions that constrain outputs to stay safe, on-topic, and aligned with intended use.", tags: ["AI","guardrails","safety"] },
  { q: "Which technique most directly improves an assistant's adherence to a required output format (e.g., always returning JSON)?", opts: ["Raising the temperature","Removing the system prompt","Sending fewer tokens","Giving clear instructions and examples in the prompt, and/or using structured-output/schema features"], a: 3, e: "Explicit formatting instructions, few-shot examples, and structured-output or schema-enforcement features reliably steer the model toward the desired format.", tags: ["AI","instruction-following","structured-output"] },
  { q: "A 'prompt injection' attack against an assistant typically works by:", opts: ["Overheating the server","Embedding malicious instructions in user input or fetched content to override the assistant's intended behavior","Sending too many tokens","Lowering the temperature remotely"], a: 1, e: "Prompt injection slips adversarial instructions into the input (including retrieved or pasted content) to hijack or subvert the assistant's behavior.", tags: ["AI","prompt-injection","guardrails"] },
  { q: "Why is it risky for an assistant to treat untrusted retrieved web content as if it were trusted instructions?", opts: ["It uses more electricity","Retrieved content is always too short","That content may contain prompt-injection instructions that manipulate the assistant","It improves accuracy too much"], a: 2, e: "Untrusted content can carry hidden instructions; treating it as commands lets attackers perform indirect prompt injection, so it should be handled as data, not directives.", tags: ["AI","prompt-injection","safety"] },
  // Level 16 — Multimodal Models
  { q: "What does it mean for a model to be 'multimodal'?", opts: ["It runs in multiple data centers","It can process and/or generate more than one type of data, such as text plus images or audio","It supports multiple languages only","It has multiple temperature settings"], a: 1, e: "A multimodal model handles multiple modalities (e.g., text, images, audio, video) rather than being limited to text alone.", tags: ["AI","multimodal","vision"] },
  { q: "A vision-capable LLM is given a photo of a handwritten note and asked to transcribe it. This task is essentially:", opts: ["Text-to-speech","Optical character recognition (OCR) / image understanding","Image generation","Embedding compression"], a: 1, e: "Reading text out of an image is OCR-style image understanding, a common capability of modern vision-language models.", tags: ["AI","multimodal","OCR"] },
  { q: "Which describes a text-to-image generation model?", opts: ["It converts speech into text","It summarizes a document","It produces a new image based on a text description (prompt)","It transcribes audio into subtitles"], a: 2, e: "Text-to-image models generate novel images conditioned on a natural-language prompt describing the desired picture.", tags: ["AI","image-generation","multimodal"] },
  { q: "Speech-to-text (automatic speech recognition) systems primarily:", opts: ["Generate music from text","Translate images into 3D models","Compress video files","Convert spoken audio into written text"], a: 3, e: "Speech-to-text / ASR models transcribe audio of human speech into text, which can then be processed further.", tags: ["AI","speech-to-text","audio"] },
  { q: "Which is a realistic use case for a vision-language model?", opts: ["Encrypting a database","Describing the contents of an image, answering questions about a chart, or extracting fields from a scanned form","Defragmenting a hard drive","Generating random numbers for cryptography"], a: 1, e: "Vision-language models excel at understanding images, including visual question answering, chart reading, and document field extraction.", tags: ["AI","multimodal","vision"] },
  { q: "How do many multimodal LLMs incorporate an image into the model's processing?", opts: ["By printing the image and scanning it","By converting it to a sound file first","By encoding the image into embeddings/tokens that are fed into the model alongside text tokens","By emailing it to a human"], a: 2, e: "Images are typically passed through an encoder that produces representations (tokens/embeddings) combined with text tokens for joint processing.", tags: ["AI","multimodal","embeddings"] },
  { q: "A limitation to keep in mind for AI image generation is that:", opts: ["It can never produce any text-like shapes","Generated images may contain inaccuracies or artifacts and can reflect biases in training data","It always produces perfect, fully accurate diagrams","It guarantees copyright-free output in every jurisdiction"], a: 1, e: "Image generators can produce visual artifacts, factual inaccuracies (e.g., wrong details), and biased outputs, and legal status of outputs varies, so results need review.", tags: ["AI","image-generation","limitations"] },
  { q: "Which task combines multiple modalities in a single request?", opts: ["Asking a text-only model to define a word","Counting characters in a string","Sorting a list of numbers","Uploading a chart image and asking the model to explain the trend in writing"], a: 3, e: "Providing an image and requesting a textual explanation uses both vision and language, the hallmark of a multimodal interaction.", tags: ["AI","multimodal","use-cases"] },
  // Level 17 — AI Safety & Alignment
  { q: "In AI, what does 'alignment' broadly refer to?", opts: ["Arranging GPUs in a row","Making a model's behavior consistent with human values, intentions, and safety goals","Aligning text to the left margin","Synchronizing model clocks"], a: 1, e: "Alignment is the effort to ensure AI systems act in accordance with human intentions and values, behaving helpfully and safely.", tags: ["AI","alignment","safety"] },
  { q: "What does RLHF (reinforcement learning from human feedback) use to shape a model's behavior?", opts: ["Random weight resets","Human preference data, often via a reward model that scores outputs","Only the original pretraining corpus","Lower temperature settings"], a: 1, e: "RLHF trains the model using human preferences (frequently through a learned reward model) to make outputs more helpful, harmless, and aligned.", tags: ["AI","RLHF","alignment"] },
  { q: "Why do aligned assistants sometimes refuse a request?", opts: ["They ran out of tokens","Refusals are random","Safety training and policies cause them to decline harmful, dangerous, or disallowed requests","They only refuse on weekends"], a: 2, e: "Refusals are a deliberate safety behavior: alignment training and guardrails lead the model to decline requests that could cause harm or violate policy.", tags: ["AI","refusals","safety"] },
  { q: "What is a 'jailbreak' in the context of LLMs?", opts: ["Speeding up the model","A way to reduce token cost","A method to fine-tune for free","A prompt crafted to bypass a model's safety guardrails and elicit disallowed output"], a: 3, e: "A jailbreak is an adversarial prompt designed to circumvent the model's safety restrictions and make it produce content it would normally refuse.", tags: ["AI","jailbreak","safety"] },
  { q: "Why does alignment matter as models become more capable?", opts: ["It makes them cheaper to host","More capable systems can cause greater harm if misaligned, so steering them toward safe, intended behavior becomes increasingly important","It only affects image models","It is purely a branding concern"], a: 1, e: "Greater capability raises the stakes of misbehavior, so ensuring models reliably do what we intend is critical for safe deployment.", tags: ["AI","alignment","safety"] },
  { q: "Which is a known challenge with safety guardrails on LLMs?", opts: ["They make the model deterministic","They can sometimes be bypassed by clever jailbreaks or be overly cautious (false refusals)","They eliminate all hallucinations","They have no effect on outputs"], a: 1, e: "Guardrails are imperfect: adversarial prompts may evade them, and overly strict rules can cause unnecessary refusals of benign requests.", tags: ["AI","guardrails","refusals"] },
  { q: "A common step in turning a raw pretrained model into a helpful assistant is:", opts: ["Deleting most of its weights","Lowering the context window","Running it only at temperature 0","Instruction tuning and alignment (e.g., supervised fine-tuning plus preference optimization like RLHF)"], a: 3, e: "Pretrained models are typically instruction-tuned and aligned (via SFT and methods such as RLHF) to follow instructions helpfully and safely.", tags: ["AI","alignment","instruction-tuning"] },
  { q: "What is 'red-teaming' an AI model?", opts: ["Painting the data center red","Deliberately probing the model with adversarial inputs to find harmful behaviors or weaknesses before deployment","Training only on red-colored images","A way to increase throughput"], a: 1, e: "Red-teaming stress-tests a model by attempting to elicit unsafe or undesirable outputs, helping developers fix vulnerabilities prior to release.", tags: ["AI","red-teaming","safety"] },
  // Level 18 — Bias & Ethics
  { q: "Where does bias in an LLM most fundamentally originate?", opts: ["Only from the user's prompt wording","From patterns, imbalances, and stereotypes present in the training data (and choices in the pipeline)","From the temperature setting alone","From the size of the context window"], a: 1, e: "Models learn from large datasets that contain societal and historical biases, which can be reflected and even amplified in their outputs.", tags: ["AI","bias","ethics"] },
  { q: "Why is privacy a concern when using LLMs with user data?", opts: ["Models cannot read text","Sensitive data sent to or used to train a model could be exposed, retained, or memorized if not handled carefully","Privacy only matters for images","Text data has no privacy implications"], a: 1, e: "Personal or confidential information can be logged, retained, or potentially memorized, so careful data handling and policies are essential.", tags: ["AI","privacy","ethics"] },
  { q: "Which is a legitimate copyright concern around generative AI?", opts: ["Models use too little electricity","Outputs are always automatically public domain worldwide","Training on copyrighted material and producing outputs that may resemble protected works raise unresolved legal and ethical questions","Copyright never applies to any AI output"], a: 2, e: "The use of copyrighted data in training and the status/ownership of generated outputs are actively debated legal and ethical issues.", tags: ["AI","copyright","ethics"] },
  { q: "What does 'fairness' aim to address in AI systems?", opts: ["Making the model run at equal speed on all devices","Avoiding systematically disadvantaging particular groups in the model's outputs or decisions","Charging all users the same price","Equal token limits for everyone"], a: 1, e: "Fairness focuses on preventing discriminatory or inequitable treatment of individuals or groups in model behavior and outcomes.", tags: ["AI","fairness","ethics"] },
  { q: "A hiring tool built on an LLM consistently rates candidates from one demographic lower for equivalent qualifications. This is an example of:", opts: ["A streaming error","A tokenization limit","Harmful bias that can lead to discriminatory outcomes","Correct, expected behavior"], a: 2, e: "Systematically lower ratings for equally qualified people from a group reflects biased, potentially discriminatory behavior that must be detected and mitigated.", tags: ["AI","bias","fairness"] },
  { q: "Which practice supports transparency and responsible AI use?", opts: ["Hiding from users that they are interacting with AI","Disclosing AI involvement, documenting limitations, and being clear about data use","Never logging anything for any reason","Maximizing temperature for honesty"], a: 1, e: "Transparency includes disclosing AI use, documenting model limitations and intended use, and being clear about how data is handled.", tags: ["AI","transparency","ethics"] },
  { q: "A responsible way to reduce privacy risk when sending prompts to a third-party LLM API is to:", opts: ["Always include full customer records for context","Minimize or redact sensitive personal data and follow the provider's data-retention and usage policies","Disable all security to speed things up","Send data to as many providers as possible"], a: 1, e: "Data minimization, redaction of personal information, and adherence to retention/usage terms reduce exposure of sensitive data.", tags: ["AI","privacy","responsible-use"] },
  { q: "Why can LLMs sometimes amplify rather than merely reflect societal biases?", opts: ["They always output the rarest token","Optimization toward common patterns can reinforce majority/stereotypical associations in outputs","They are immune to training data","Bias only exists in the prompt"], a: 1, e: "By favoring frequent patterns, models can strengthen prevailing stereotypes present in data, so outputs may exaggerate existing biases.", tags: ["AI","bias","ethics"] },
  // Level 19 — AI Agents & Tool Use
  { q: "In the context of LLMs, what is 'tool calling' (a.k.a. function calling)?", opts: ["Calling the customer support line","The model deciding to invoke an external function/API and producing structured arguments for it","Renaming a variable","Increasing the temperature"], a: 1, e: "Tool/function calling lets the model output a structured request to run an external function, enabling it to fetch data or take actions beyond text generation.", tags: ["AI","tool-calling","agents"] },
  { q: "What distinguishes an 'AI agent' from a single one-shot LLM call?", opts: ["Agents never use any model","An agent can plan and take multiple steps, often using tools and observations in a loop to accomplish a goal","Agents only work at temperature 0","Agents cannot call APIs"], a: 1, e: "An agent operates iteratively, reasoning, calling tools, observing results, and continuing, rather than producing a single direct response.", tags: ["AI","agents","planning"] },
  { q: "Why is giving an LLM a calculator or code-execution tool helpful?", opts: ["It raises the temperature","It reduces the context window","It lets the model offload exact computation, improving reliability on math the model would otherwise approximate","It disables safety filters"], a: 2, e: "Delegating arithmetic or logic to a precise tool overcomes the model's tendency to approximate calculations, yielding correct results.", tags: ["AI","tool-calling","reasoning"] },
  { q: "In a typical tool-use loop, after the model requests a tool call, what happens next?", opts: ["The conversation ends immediately","The model deletes the tool","The user must restart the app","The application runs the tool and returns the result to the model, which then continues reasoning or responds"], a: 3, e: "The host application executes the requested tool, feeds the output back as a tool/result message, and the model uses it to proceed or finalize an answer.", tags: ["AI","tool-calling","agents"] },
  { q: "Which scenario is a good fit for an agentic, multi-step approach rather than a single prompt?", opts: ["Defining one vocabulary word","A task requiring several dependent steps, like searching, reading results, and then compiling a researched summary","Echoing the user's text","Converting Celsius to Fahrenheit once"], a: 1, e: "Agents shine on complex tasks needing sequential decisions and tool use, where intermediate results inform later steps.", tags: ["AI","agents","use-cases"] },
  { q: "How does the model typically receive the set of tools it is allowed to use?", opts: ["It guesses them randomly","The developer provides tool definitions/schemas (names, descriptions, and parameters) the model can choose from","Tools are hard-coded into the model weights only","It downloads them from the internet automatically"], a: 1, e: "Developers declare available tools with structured schemas describing each function's purpose and parameters, and the model selects and fills them as needed.", tags: ["AI","tool-calling","API"] },
  { q: "A key reliability risk when letting an autonomous agent take real-world actions is that:", opts: ["It always succeeds perfectly","It cannot use any tools","It may take incorrect or unintended actions, so safeguards like confirmations, scoping, and limits are important","It removes the need for testing"], a: 2, e: "Agents can err or be manipulated, so guardrails such as human confirmation, permission scoping, and step/cost limits help contain mistakes.", tags: ["AI","agents","safety"] },
  { q: "What is one benefit of the model emitting structured arguments (e.g., a defined schema) for a tool call?", opts: ["It guarantees the answer is correct","The application can reliably parse and execute the call programmatically","It removes the need for the tool","It increases hallucinations on purpose"], a: 1, e: "Structured, schema-conforming arguments are machine-parseable, letting the application execute the tool deterministically and safely.", tags: ["AI","tool-calling","structured-output"] },
  // Level 20 — The Modern AI Landscape
  { q: "What does it mean for a model to be 'open-weight' (often loosely called open-source)?", opts: ["Its training is livestreamed","Its trained parameters are publicly downloadable so others can run or adapt it themselves","It has no safety training","It is always larger than closed models"], a: 1, e: "Open-weight models release their parameters for download, enabling self-hosting and fine-tuning, in contrast to closed models accessed only via API.", tags: ["AI","open-weight","landscape"] },
  { q: "Which of these is a family of openly available large language models?", opts: ["Llama","A type of GPU only","An embedding database","A tokenizer standard"], a: 0, e: "Meta's Llama is a well-known family of open-weight LLMs widely used for self-hosting and fine-tuning.", tags: ["AI","open-weight","landscape"] },
  { q: "Which company develops the Claude family of models?", opts: ["Google","Anthropic","Meta","Mistral AI"], a: 1, e: "Claude is developed by Anthropic; Google develops Gemini, Meta develops Llama, and Mistral AI develops the Mistral models.", tags: ["AI","providers","landscape"] },
  { q: "What is the main purpose of AI benchmarks (e.g., reasoning, coding, or knowledge test suites)?", opts: ["To set the model's price","To provide standardized tasks for comparing models' capabilities","To encrypt model weights","To replace human users entirely"], a: 1, e: "Benchmarks offer common, repeatable tasks so different models can be compared on capabilities like reasoning, coding, or knowledge.", tags: ["AI","benchmarks","evaluation"] },
  { q: "A noteworthy trend in LLMs during 2024-2026 has been:", opts: ["Shrinking context windows back to a few hundred tokens","The rise of multimodal models and longer context windows alongside both strong closed and open-weight options","The disappearance of open-weight models","A move away from any safety training"], a: 1, e: "Recent years saw rapid growth in multimodal capabilities, much larger context windows, and a vibrant ecosystem of both proprietary and open-weight models.", tags: ["AI","trends","landscape"] },
  { q: "A common limitation of public benchmark scores is that:", opts: ["They are always perfectly representative of real-world use","They can be gamed or affected by data contamination, so high scores don't guarantee real-world quality","They measure only electricity usage","They cannot be compared across models"], a: 1, e: "Benchmarks can suffer from training-data contamination or overfitting, so leaderboard scores may not fully reflect practical performance.", tags: ["AI","benchmarks","limitations"] },
  { q: "Which is a genuine trade-off when choosing open-weight models over closed API models?", opts: ["Open-weight models require no compute to run","Self-hosting open-weight models gives control and data locality but shifts infrastructure, scaling, and maintenance burden to you","Closed models can always be fine-tuned for free","There are no differences at all"], a: 1, e: "Open-weight self-hosting offers customization and data control but requires you to provide and manage the serving infrastructure, unlike a managed API.", tags: ["AI","open-weight","landscape"] },
  { q: "Which pairing of provider and model family is correct?", opts: ["OpenAI - Gemini","Google - Gemini","Anthropic - Llama","Meta - GPT"], a: 1, e: "Gemini is Google's model family; OpenAI makes GPT, Anthropic makes Claude, and Meta makes Llama.", tags: ["AI","providers","landscape"] },
];
